select @@fields into #t from @@table a left join dmttct b on a.ma_ct = b.ma_ct and a.ma_ttct = b.ma_ttct where @@key order by stt
insert into #t select @user_id, @ma_ct, ma_ttct, ten_ttct, 0, 0, 0, 0, stt from dmttct where ma_ct = @ma_ct and ma_ttct not in (select ma_ttct from #t) and right_yn = 1
select * from #t order by stt
drop table #t








  &DefaultButton;




function dir$sysrightstatus(p){
  this.constructor(p);
}
dir$sysrightstatus.prototype = new DirEvent();
dir$sysrightstatus.prototype.beforeInit = function(){
  var p = this._dir;
  if (p.options.action == 'EDIT') {
    p.field('ma_ct').disabled = true;
    p.field('username').disabled = true;
  }
}
dir$sysrightstatus.prototype.afterInit = function(){
  var p = this._dir;
  p.options.dataChanged = true;
}
dir$sysrightstatus.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
    case 'ma_ct':
      p.reloadGrid(0, ['ma_ct', 'C', v]);
      break;
    default:
      break;
  }
}








select @@fields into #@@table from @@table a where [%whereFieldKey]
[%updateRef]
select * from #@@table
drop table #@@table
if @action <> 'NEW' select username, nickname from vsysuserinfo where user_id = @user_id







select @user_id = user_id, @status = 1 from vsysuserinfo where username = @username







delete sysrightstatus2 where [%whereFieldKey]
EXEC ISWIFTStoredUpdateRightStatus @user_id, @ma_ct, @@userId, @@admin







update @@table set user_id = @user_id where user_id = @@old_user_id and ma_ct = @@old_ma_ct
update @@table set datetime2 = getdate(), user_id2 = @@userId where [%whereFieldKey]

delete sysrightstatus2 where user_id = @@old_user_id and ma_ct = @@old_ma_ct







if exists(select 1 from @sysrightstatus2 where a_view = 1 or a_new = 1 or a_edit = 1 or a_del = 1) begin
	insert into sysrightstatus2 select @user_id, @ma_ct, ma_ttct, a_view, a_new, a_edit, a_del from @sysrightstatus2 
end
EXEC ISWIFTStoredUpdateRightStatus @user_id, @ma_ct, @@userId, @@admin
